-- GenDB engine variant Q05-commuted_comparisons: template q05.sql, kind commuted_comparisons (generated by generate.py; frozen)
SELECT
  n_name,
  SUM(l_extendedprice * (
    1 - l_discount
  )) AS revenue
FROM customer, orders, lineitem, supplier, nation, region
WHERE
  o_custkey = c_custkey
  AND o_orderkey = l_orderkey
  AND s_suppkey = l_suppkey
  AND s_nationkey = c_nationkey
  AND n_nationkey = s_nationkey
  AND r_regionkey = n_regionkey
  AND $1 = r_name
  AND $2 <= o_orderdate
  AND $2 + INTERVAL '1 YEAR' > o_orderdate
GROUP BY
  n_name
ORDER BY
  revenue DESC
